// Standard Disease Discussion Template (Clinova) — every section is optional
// so a note only renders the parts that apply / have been authored.
export interface DiseaseNote {
  id: string
  name: string
  unitId: string
  specialty: string
  overview: string
  kenyaContext?: string
  pathophysiology?: string
  diagram?: string
  pathophysiologyDiagram?: string
  keyDrugs: DiseaseNoteDrug[]

  // §1 Identification
  alternativeNames?: string[]
  icd10?: string
  icd11?: string
  // §2 Definition
  definition?: string
  // §3 Epidemiology
  epidemiology?: string
  // §4 Etiology
  etiology?: string[]
  // §5 Risk factors
  riskFactors?: DiseaseNoteRiskFactors
  // §6 Pathophysiology (reuses `pathophysiology`)
  // §7 Classification
  classification?: string[]
  // §8 Clinical features
  clinicalFeatures?: string[]
  // §9 Signs
  signs?: string[]
  // §10 Red flags
  redFlags?: string[]
  // §11 Complications
  complications?: string[]
  // §12 Differential diagnosis
  differential?: DiseaseNoteDifferential[]
  // §15 Investigations
  investigations?: string[]
  // §16 Diagnosis
  diagnosis?: string
  // §17 Severity scores
  severityScores?: string[]
  // §18 Management
  management?: DiseaseNoteManagement
  // §19 Non-pharmacological
  nonPharmacological?: string[]
  // §20 Pharmacological (reuses `keyDrugs`)
  // §21 Surgical
  surgical?: string
  // §22 Monitoring (reuses `monitoring`)
  // §23 Prevention
  prevention?: string[]
  // §24 Prognosis
  prognosis?: string
  // §25 Patient counseling
  counseling?: string[]
  // §26 Special populations
  specialPopulations?: string[]
  // §27 Clinical pearls
  clinicalPearls?: string[]
  // §28 Common mistakes
  commonMistakes?: string[]
  // §29 Drug therapy problems
  drugTherapyProblems?: string[]
  // §30 Guidelines
  guidelines?: string[]
  // §32 FAQ
  faq?: DiseaseNoteFAQ[]
  // §33 Clinical case
  caseExample?: DiseaseNoteCase
  // §34 Self-assessment (reuses `mcqs`)
  // §35 References
  references?: string[]
  // §36 Metadata
  metadata?: DiseaseNoteMetadata

  monitoring: string
  mcqs: DiseaseNoteMCQ[]
}

